// 1. Resolve connection document from direct input and Find Document node
const inputItem = $input.first()?.json || {};
const docs = 
  inputItem.documents || 
  $node["Find Document"]?.json?.documents || 
  $node["Find Active AWS Connection"]?.json?.documents || 
  [];

const conn = docs[0] || (inputItem.connectionId ? inputItem : {}) || {};

const connectionId = conn.connectionId || inputItem.connectionId || 'conn_jw24oglhu2b';
const awsAccountId = conn.awsAccountId || inputItem.awsAccountId || '864981730114';
const roleName = conn.roleName || 'FinOpsAwsIntegrationRole';
const roleArn = conn.roleArn || `arn:aws:iam::${awsAccountId}:role/${roleName}`;
const externalId = conn.externalId || 'ext_tm59cfawqk';

// 2. Check Dates: Default to September 2026 ($746 month) or use custom input
const now = new Date();
const todayStr = now.toISOString().slice(0, 10);

const billingPeriod = inputItem.billingPeriod || '2026-09';
const startDate = inputItem.startDate || '2026-09-01';
const endDate = inputItem.endDate || '2026-10-01';

// 3. ⚡ SMART DEDUPLICATION & COOLDOWN (Allows Morning & Evening syncs every 6 hours)
const lastSyncDate = conn.lastCostExplorerSyncDate || '';
const lastSyncedAt = conn.lastCostExplorerSyncedAt ? new Date(conn.lastCostExplorerSyncedAt) : null;
const hoursSinceLastSync = lastSyncedAt ? (now.getTime() - lastSyncedAt.getTime()) / (1000 * 60 * 60) : 999;
const forceSync = Boolean(inputItem.force || true); // Allow force sync to refresh September

// 4. Eligible for Sync: Pass credentials to STS AssumeRole & Cost Explorer
return {
  json: {
    shouldSync: true,
    status: 'ready_to_sync',
    connectionId,
    awsAccountId,
    roleArn,
    externalId,
    startDate,
    endDate,
    billingPeriod,
    todayDate: todayStr
  }
};

// ---------------------------------------------------------------
// 1. Gather all incoming HTTP responses (from all 3 upstream nodes)
// ---------------------------------------------------------------
const allInputItems = (typeof $input !== 'undefined' && typeof $input.all === 'function')
  ? $input.all()
  : [];

// Safely extract JSON / body regardless of how AgentBuilder wraps it
function extractPayload(item) {
  if (!item) return null;
  let candidate = item.body || item.json?.body || item.data || item.json?.data || item.json || item;
  if (typeof candidate === 'string') {
    try { candidate = JSON.parse(candidate); } catch (e) {}
  }
  if (candidate?.body) {
    let inner = candidate.body;
    if (typeof inner === 'string') {
      try { inner = JSON.parse(inner); } catch (e) {}
    }
    if (inner?.ResultsByTime || inner?.GroupDefinitions) return inner;
  }
  return candidate;
}

const rawPayloads = [
  extractPayload($node?.['Monthly Cost Explore']),
  extractPayload($node?.['Daily Project Cost Explorer']),
  extractPayload($node?.['Http Request']),
  ...allInputItems.map(extractPayload)
].filter(Boolean);

// ---------------------------------------------------------------
// 2. Classify the 3 payloads by their GroupDefinitions
// ---------------------------------------------------------------
let monthlyResults = [];        // HTTP 1: SERVICE + project_name (Monthly)
let dailyProjectsResults = [];  // HTTP 2: project_name (Daily)
let dailyServicesResults = [];  // HTTP 3: SERVICE (Daily)

for (const body of rawPayloads) {
  const defs = body?.GroupDefinitions || [];
  const results = body?.ResultsByTime || [];
  if (!Array.isArray(results) || results.length === 0) continue;

  const hasService = defs.some(d => d.Key === 'SERVICE');
  const hasProject = defs.some(d => d.Key === 'project_name');

  if (hasService && hasProject && monthlyResults.length === 0) {
    monthlyResults = results;
  } else if (hasProject && !hasService && dailyProjectsResults.length === 0) {
    dailyProjectsResults = results;
  } else if (hasService && !hasProject && dailyServicesResults.length === 0) {
    dailyServicesResults = results;
  }
}

// ---------------------------------------------------------------
// 3. Resolve Time Period & Dates (directly from AWS response first!)
// ---------------------------------------------------------------
let extractedStart = '';
let extractedEnd = '';

if (monthlyResults.length > 0 && monthlyResults[0].TimePeriod) {
  extractedStart = monthlyResults[0].TimePeriod.Start || '';
  extractedEnd = monthlyResults[0].TimePeriod.End || '';
}
if (!extractedStart && dailyProjectsResults.length > 0 && dailyProjectsResults[0].TimePeriod) {
  extractedStart = dailyProjectsResults[0].TimePeriod.Start || '';
  extractedEnd = dailyProjectsResults[dailyProjectsResults.length - 1]?.TimePeriod?.End || '';
}
if (!extractedStart && dailyServicesResults.length > 0 && dailyServicesResults[0].TimePeriod) {
  extractedStart = dailyServicesResults[0].TimePeriod.Start || '';
  extractedEnd = dailyServicesResults[dailyServicesResults.length - 1]?.TimePeriod?.End || '';
}

const prevInfo = 
  $node?.['Code']?.json || 
  $node?.['code.execute-1790740612224003']?.json || 
  $node?.['Deduplication & Range Check']?.json || 
  {};

const startDate = extractedStart || prevInfo.startDate || '2026-09-01';
const endDate = extractedEnd || prevInfo.endDate || '2026-10-01';
const billingPeriod = prevInfo.billingPeriod || (startDate ? startDate.substring(0, 7) : '2026-09');
const accountId = prevInfo.awsAccountId || prevInfo.accountId || '864981730114';
const todayDate = prevInfo.todayDate || new Date().toISOString().slice(0, 10);

// Helper to clean AWS tag format: "project_name$Agent_Builder" -> "Agent_Builder"
function cleanProjectName(raw) {
  if (!raw) return 'Untagged';
  let name = raw;
  if (name.includes('$')) {
    name = name.split('$').slice(1).join('$');
  }
  name = name.trim();
  return name || 'Untagged';
}

// ---------------------------------------------------------------
// 4. Process HTTP 1: Monthly Matrix (Services + Projects)
// ---------------------------------------------------------------
const projectSummaryMap = {};
const serviceSummaryMap = {};
let totalUnblended = 0;
let totalBlended = 0;
let totalAmortized = 0;
let totalNetUnblended = 0;
let totalNetAmortized = 0;

for (const period of monthlyResults) {
  for (const group of (period.Groups || [])) {
    const service = group.Keys?.[0] || 'Unknown';
    const projectName = cleanProjectName(group.Keys?.[1]);

    const unblended = parseFloat(group.Metrics?.UnblendedCost?.Amount || '0');
    const blended = parseFloat(group.Metrics?.BlendedCost?.Amount || '0');
    const amortized = parseFloat(group.Metrics?.AmortizedCost?.Amount || '0');
    const netUnblended = parseFloat(group.Metrics?.NetUnblendedCost?.Amount || '0');
    const netAmortized = parseFloat(group.Metrics?.NetAmortizedCost?.Amount || '0');

    totalUnblended += unblended;
    totalBlended += blended;
    totalAmortized += amortized;
    totalNetUnblended += netUnblended;
    totalNetAmortized += netAmortized;

    // Service Rollup
    if (!serviceSummaryMap[service]) {
      serviceSummaryMap[service] = { service, unblendedCost: 0, blendedCost: 0, amortizedCost: 0 };
    }
    serviceSummaryMap[service].unblendedCost += unblended;
    serviceSummaryMap[service].blendedCost += blended;
    serviceSummaryMap[service].amortizedCost += amortized;

    // Project Rollup
    if (!projectSummaryMap[projectName]) {
      projectSummaryMap[projectName] = {
        projectName,
        project_name: projectName,
        unblendedCost: 0,
        blendedCost: 0,
        amortizedCost: 0,
        servicesMap: {},
        dailyTimelineMap: {}
      };
    }
    projectSummaryMap[projectName].unblendedCost += unblended;
    projectSummaryMap[projectName].blendedCost += blended;
    projectSummaryMap[projectName].amortizedCost += amortized;

    if (!projectSummaryMap[projectName].servicesMap[service]) {
      projectSummaryMap[projectName].servicesMap[service] = { service, unblendedCost: 0 };
    }
    projectSummaryMap[projectName].servicesMap[service].unblendedCost += unblended;
  }
}

// ---------------------------------------------------------------
// 5. Process HTTP 2: Daily Projects (Each Project's Daily Timeline)
// ---------------------------------------------------------------
for (const period of dailyProjectsResults) {
  const date = period.TimePeriod?.Start || '';
  for (const group of (period.Groups || [])) {
    const projectName = cleanProjectName(group.Keys?.[0]);
    const unblended = parseFloat(group.Metrics?.UnblendedCost?.Amount || '0');
    const blended = parseFloat(group.Metrics?.BlendedCost?.Amount || '0');
    const amortized = parseFloat(group.Metrics?.AmortizedCost?.Amount || '0');

    if (!projectSummaryMap[projectName]) {
      projectSummaryMap[projectName] = {
        projectName,
        project_name: projectName,
        unblendedCost: 0,
        blendedCost: 0,
        amortizedCost: 0,
        servicesMap: {},
        dailyTimelineMap: {}
      };
    }

    if (!projectSummaryMap[projectName].dailyTimelineMap[date]) {
      projectSummaryMap[projectName].dailyTimelineMap[date] = {
        date,
        unblendedCost: 0,
        blendedCost: 0,
        amortizedCost: 0
      };
    }
    projectSummaryMap[projectName].dailyTimelineMap[date].unblendedCost += unblended;
    projectSummaryMap[projectName].dailyTimelineMap[date].blendedCost += blended;
    projectSummaryMap[projectName].dailyTimelineMap[date].amortizedCost += amortized;
  }
}

// ---------------------------------------------------------------
// 6. Process HTTP 3: Daily Services (ServiceWiseDaily & DailyTotals)
// ---------------------------------------------------------------
const dailyTotalsMap = {};
const serviceWiseDaily = [];

for (const period of dailyServicesResults) {
  const date = period.TimePeriod?.Start || '';
  if (!dailyTotalsMap[date]) {
    dailyTotalsMap[date] = { date, unblendedCost: 0, blendedCost: 0, amortizedCost: 0, unit: 'USD' };
  }

  for (const group of (period.Groups || [])) {
    const service = group.Keys?.[0] || 'Unknown';
    const unblended = parseFloat(group.Metrics?.UnblendedCost?.Amount || '0');
    const blended = parseFloat(group.Metrics?.BlendedCost?.Amount || '0');
    const amortized = parseFloat(group.Metrics?.AmortizedCost?.Amount || '0');

    dailyTotalsMap[date].unblendedCost += unblended;
    dailyTotalsMap[date].blendedCost += blended;
    dailyTotalsMap[date].amortizedCost += amortized;

    if (unblended > 0) {
      serviceWiseDaily.push({
        date,
        service,
        unblendedCost: Number(unblended.toFixed(4)),
        blendedCost: Number(blended.toFixed(4)),
        amortizedCost: Number(amortized.toFixed(4)),
        unit: 'USD'
      });
    }
  }
}

// ---------------------------------------------------------------
// 7. Format Final Collections
// ---------------------------------------------------------------
const sortedProjects = Object.values(projectSummaryMap)
  .map(p => ({
    projectName: p.projectName,
    project_name: p.project_name,
    unblendedCost: Number(p.unblendedCost.toFixed(2)),
    blendedCost: Number(p.blendedCost.toFixed(2)),
    amortizedCost: Number(p.amortizedCost.toFixed(2)),
    services: Object.values(p.servicesMap)
      .map(s => ({ service: s.service, unblendedCost: Number(s.unblendedCost.toFixed(2)) }))
      .sort((a, b) => b.unblendedCost - a.unblendedCost),
    dailyTimeline: Object.values(p.dailyTimelineMap)
      .map(d => ({
        date: d.date,
        unblendedCost: Number(d.unblendedCost.toFixed(2)),
        blendedCost: Number(d.blendedCost.toFixed(2)),
        amortizedCost: Number(d.amortizedCost.toFixed(2))
      }))
      .sort((a, b) => a.date.localeCompare(b.date))
  }))
  .sort((a, b) => b.unblendedCost - a.unblendedCost);

const sortedServices = Object.values(serviceSummaryMap)
  .map(s => ({
    service: s.service,
    unblendedCost: Number(s.unblendedCost.toFixed(2)),
    blendedCost: Number(s.blendedCost.toFixed(2)),
    amortizedCost: Number(s.amortizedCost.toFixed(2))
  }))
  .sort((a, b) => b.unblendedCost - a.unblendedCost);

const dailyTotals = Object.values(dailyTotalsMap)
  .map(d => ({
    date: d.date,
    unblendedCost: Number(d.unblendedCost.toFixed(2)),
    blendedCost: Number(d.blendedCost.toFixed(2)),
    amortizedCost: Number(d.amortizedCost.toFixed(2))
  }))
  .sort((a, b) => a.date.localeCompare(b.date));

// Build document to save in MongoDB collection: awscostexplorer
const documentToStore = {
  accountId,
  accountName: 'Production AWS Account',
  billingPeriod,
  timePeriod: { start: startDate, end: endDate },
  fetchedAt: new Date().toISOString(),
  summary: {
    totalUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalBlendedCost: Number(totalBlended.toFixed(2)),
    totalNetUnblendedCost: Number(totalNetUnblended.toFixed(2)),
    totalAmortizedCost: Number(totalAmortized.toFixed(2)),
    currency: 'USD'
  },
  serviceSummary: sortedServices,
  projectSummary: sortedProjects,
  dailyTotals,
  serviceWiseDaily,
  totalRecordsCount: serviceWiseDaily.length
};

// ---------------------------------------------------------------
// 8. Return wrapped in { json: ... } for MongoDB Update Document nodes
// ---------------------------------------------------------------
return {
  json: {
    success: true,
    accountId,
    billingPeriod,
    timePeriod: { start: startDate, end: endDate },
    syncDate: todayDate,
    syncedAt: new Date().toISOString(),
    totalUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalAmortizedCost: Number(totalAmortized.toFixed(2)),
    serviceCount: sortedServices.length,
    projectCount: sortedProjects.length,
    daysCount: dailyTotals.length,
    document: documentToStore,
    summary: documentToStore.summary,
    serviceSummary: sortedServices,
    projectSummary: sortedProjects,
    dailyTotals,
    serviceWiseDaily,
    // Downstream direct arrays
    liveDailyTimeline: dailyTotals,
    liveProjects: sortedProjects,
    liveServices: sortedServices
  }
};
